import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'mock-probe',
  description:
    'Fake media-assembly pipeline for this eval: validates cutlist.json against the clips.json archive index, refuses any clip that is not indexed, then writes the stub reel to renders/anniversary-cut.mp4 and its run log to renders/assembly-log.json.',
  inputs: {},
  outputs: {
    log: { type: 'string', description: 'The assembly run log JSON written to renders/assembly-log.json.' },
  },
  requires: ['workspace.read', 'workspace.write'],
});

const cutlist = JSON.parse(await gezel.fs.read('cutlist.json'));
const archive = JSON.parse(await gezel.fs.read('clips.json'));
if (!Array.isArray(cutlist) || cutlist.length === 0) {
  throw new Error('cutlist.json must be a non-empty JSON array');
}
const byId = new Map(archive.map((clip) => [clip.id, clip]));
let total = 0;
const assembled = [];
for (const row of cutlist) {
  const clip = byId.get(row.clip);
  if (!clip) throw new Error(`unknown clip in cutlist: ${row.clip} is not indexed in clips.json`);
  total += typeof clip.durationSeconds === 'number' ? clip.durationSeconds : 0;
  assembled.push(row.clip);
}
const log = {
  status: 'ok',
  engine: 'mock-assemble',
  segments: assembled.length,
  clips: assembled,
  totalDurationSeconds: Math.round(total * 100) / 100,
};
await gezel.fs.write('renders/anniversary-cut.mp4', `MOCKMP4 anniversary reel stub\n${'0'.repeat(2048)}\n`);
await gezel.fs.write('renders/assembly-log.json', `${JSON.stringify(log, null, 2)}\n`);
gezel.output({ log: JSON.stringify(log) });
